#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"
#include "gui_forms/controls/pages/page_view/page_view_values/page_view_values.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// PageView's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/page_view.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks and,
// where C# lets a subclass rewrite the value, the protected virtual coerce
// hook), the compare and store, then the written hook (the touch, side
// effects and the change event, through the protected virtual
// on_<property>_changed() where Windows Forms has OnXChanged). A read is
// `(*control).x.read()`.

// What the view does with a close request no handler took (see PageViewClosePolicy). An unknown policy throws std::invalid_argument.
template <typename Declaring>
struct PageViewClosePolicyPropertyCapability {
    PropertyCell<PageViewClosePolicy, PageViewClosePolicyPropertyCapability<Declaring>> close_policy{PageViewClosePolicy::remove_when_unhandled};

    static void assign(PageViewClosePolicyPropertyCapability& capability, PageViewClosePolicy incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.close_policy), incoming);
        if (!capability.close_policy.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.close_policy));
    }
};

// What Ctrl+Tab and Ctrl+Shift+Tab do while focus is inside the view (see PageViewCtrlTab). An unknown policy throws std::invalid_argument.
template <typename Declaring>
struct PageViewCtrlTabPropertyCapability {
    PropertyCell<PageViewCtrlTab, PageViewCtrlTabPropertyCapability<Declaring>> ctrl_tab{PageViewCtrlTab::select_next};

    static void assign(PageViewCtrlTabPropertyCapability& capability, PageViewCtrlTab incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.ctrl_tab), incoming);
        if (!capability.ctrl_tab.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.ctrl_tab));
    }
};

// Whether the view registers itself as an F6 region of its window (owner decision RB-17), off by default. A view nested in another region is not registered.
template <typename Declaring>
struct PageViewFocusRegionCapability {
    PropertyCell<bool, PageViewFocusRegionCapability<Declaring>> focus_region{false};

    static void assign(PageViewFocusRegionCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.focus_region), incoming);
        if (!capability.focus_region.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.focus_region));
    }
};

// Every PageView capability, in the order the declaring class takes them.
template <typename Declaring>
struct PageViewCapabilities : public PageViewClosePolicyPropertyCapability<Declaring>,
                              public PageViewCtrlTabPropertyCapability<Declaring>,
                              public PageViewFocusRegionCapability<Declaring> {};

} // namespace gui_forms
